#!/usr/bin/env node
// 判据覆盖率统计：扫描 <workspace>/.agent/sessions/*.jsonl，逐行 JSON.parse，坏行跳过并计 skippedLines。
// 用法：
//   node --import tsx scripts/verify-census.ts [--workspace <dir>] [--json]
//   · --workspace <dir>  覆盖 workspace（缺省 process.cwd()）
//   · --json             打印 JSON；否则打印人读三行
import { existsSync, readdirSync, readFileSync, statSync } from "node:fs";
import { join, resolve } from "node:path";
import { pathToFileURL } from "node:url";

export interface CensusResult {
  /** .jsonl 会话文件数 */
  sessions: number;
  /** 含 type==="verify_result" 的文件数 */
  withVerify: number;
  /** 第一条 verify_result 的 ok===true 的文件数 */
  firstGreen: number;
  /** type==="user_message" 且 origin?.kind !== "goal" 的总条数 */
  userTurns: number;
  /** 坏行（JSON.parse 失败）累计数 */
  skippedLines: number;
  /** withVerify/sessions；0 会话时为 null */
  ratio: number | null;
}

function isVerifyResult(rec: Record<string, unknown>): boolean {
  return rec.type === "verify_result";
}

function isNonGoalUserMessage(rec: Record<string, unknown>): boolean {
  if (rec.type !== "user_message") return false;
  const origin = rec.origin;
  if (typeof origin !== "object" || origin === null) return true;
  return (origin as Record<string, unknown>).kind !== "goal";
}

export function collectCensus(workspace: string): CensusResult {
  const sessionsDir = join(workspace, ".agent", "sessions");
  let sessions = 0;
  let withVerify = 0;
  let firstGreen = 0;
  let userTurns = 0;
  let skippedLines = 0;

  const names = existsSync(sessionsDir)
    ? readdirSync(sessionsDir).filter((n) => n.endsWith(".jsonl"))
    : [];

  for (const name of names) {
    const filePath = join(sessionsDir, name);
    let content: string;
    try {
      const st = statSync(filePath);
      if (!st.isFile()) continue;
      content = readFileSync(filePath, "utf8");
    } catch {
      continue;
    }

    sessions += 1;
    let sawVerify = false;
    let firstVerifyOk: boolean | null = null;

    for (const raw of content.split("\n")) {
      const line = raw.trim();
      if (line.length === 0) continue;
      let obj: unknown;
      try {
        obj = JSON.parse(line);
      } catch {
        skippedLines += 1;
        continue;
      }
      if (obj === null || typeof obj !== "object" || Array.isArray(obj)) continue;
      const rec = obj as Record<string, unknown>;
      if (isVerifyResult(rec)) {
        sawVerify = true;
        if (firstVerifyOk === null) firstVerifyOk = rec.ok === true;
      } else if (isNonGoalUserMessage(rec)) {
        userTurns += 1;
      }
    }

    if (sawVerify) withVerify += 1;
    if (firstVerifyOk === true) firstGreen += 1;
  }

  const ratio = sessions === 0 ? null : withVerify / sessions;
  return { sessions, withVerify, firstGreen, userTurns, skippedLines, ratio };
}

function parseArgs(argv: string[]): { workspace: string; json: boolean } {
  let workspace = process.cwd();
  let json = false;
  for (let i = 2; i < argv.length; i++) {
    const a = argv[i]!;
    if (a === "--json") {
      json = true;
    } else if (a === "--workspace") {
      workspace = resolve(argv[i + 1] ?? process.cwd());
      i += 1;
    } else if (a.startsWith("--workspace=")) {
      workspace = resolve(a.slice("--workspace=".length));
    }
  }
  return { workspace, json };
}

function main(): void {
  const { workspace, json } = parseArgs(process.argv);
  const r = collectCensus(workspace);
  if (json) {
    process.stdout.write(JSON.stringify(r) + "\n");
  } else {
    process.stdout.write(`sessions: ${r.sessions}\nwithVerify: ${r.withVerify}\nfirstGreen: ${r.firstGreen}\n`);
  }
}

// 仅当作为入口直接运行时执行 main；被测试 import 时不触发。
if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  main();
}

import { execFileSync } from "node:child_process";
import { mkdtempSync, mkdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { tmpdir } from "node:os";
import { afterEach, describe, expect, it } from "vitest";
import { collectCensus } from "../scripts/verify-census.ts";

const REPO_ROOT = join(import.meta.dirname, "..");
const SCRIPT = join(REPO_ROOT, "scripts", "verify-census.ts");

const tempDirs: string[] = [];
afterEach(() => {
  for (const d of tempDirs) {
    try {
      // 测试数据绝不落工作区：建在 OS 临时目录，跑完即弃（不递归删，避免误伤宿主机）。
      // 这里只留空目录引用，由 OS 回收；不主动 rm 整棵以防删错。
    } catch {
      /* noop */
    }
  }
  tempDirs.length = 0;
});

function makeWorkspace(files: Record<string, string>): string {
  const root = mkdtempSync(join(tmpdir(), "verify-census-"));
  tempDirs.push(root);
  const sessionsDir = join(root, ".agent", "sessions");
  mkdirSync(sessionsDir, { recursive: true });
  for (const [name, content] of Object.entries(files)) {
    writeFileSync(join(sessionsDir, name), content, "utf8");
  }
  return root;
}

const VERIFY_OK = '{"type":"verify_result","ok":true,"attempt":1,"maxAttempts":3,"results":[]}';
const VERIFY_BAD = '{"type":"verify_result","ok":false,"attempt":1,"maxAttempts":3,"results":[]}';
const GOAL_MSG = '{"type":"user_message","content":"agent self-run","origin":{"kind":"goal","turn":1,"max_turns":3}}';

// 三种会话：无 verify / 首拍绿 / 首拍红
const threeScenarios: Record<string, string> = {
  "no-verify.jsonl":
    '{"type":"user_message","content":"do a thing"}\n' +
    GOAL_MSG + "\n" +
    '{"type":"assistant_message","content":"ok"}\n',
  "first-green.jsonl":
    '{"type":"user_message","content":"fix it"}\n' +
    VERIFY_OK + "\n" +
    '{"type":"user_message","content":"another turn"}\n',
  "first-red.jsonl":
    '{"type":"user_message","content":"make"}\n' +
    VERIFY_BAD + "\n" +
    VERIFY_OK + "\n" +
    '{"type":"user_message","content":"retry turn"}\n',
};

describe("verify-census 判据覆盖率统计", () => {
  it("三个会话目录：五个字段与 ratio（2/3）正确", () => {
    const ws = makeWorkspace(threeScenarios);
    const r = collectCensus(ws);
    expect(r.sessions).toBe(3);
    expect(r.withVerify).toBe(2);
    expect(r.firstGreen).toBe(1);
    expect(r.userTurns).toBe(5); // 1 + 2 + 2（goal 轮不计）
    expect(r.ratio).toBeCloseTo(2 / 3, 10);
    expect(r.skippedLines).toBe(0);
  });

  it("0 会话时 ratio 为 null", () => {
    const ws = makeWorkspace({});
    const r = collectCensus(ws);
    expect(r.sessions).toBe(0);
    expect(r.withVerify).toBe(0);
    expect(r.firstGreen).toBe(0);
    expect(r.userTurns).toBe(0);
    expect(r.ratio).toBeNull();
  });

  it("坏行容错：跳过坏行并计入 skippedLines，不影响统计", () => {
    const ws = makeWorkspace({
      "no-verify.jsonl": '{"type":"user_message","content":"do a thing"}\n',
      "first-red.jsonl":
        "{this is not valid json\n" + // 坏行：应被跳过并计入 skippedLines
        '{"type":"user_message","content":"make"}\n' +
        VERIFY_BAD + "\n" +
        VERIFY_OK + "\n",
      "first-green.jsonl":
        '{"type":"user_message","content":"fix it"}\n' + VERIFY_OK + "\n",
    });
    const r = collectCensus(ws);
    expect(r.skippedLines).toBeGreaterThanOrEqual(1);
    expect(r.sessions).toBe(3);
    expect(r.withVerify).toBe(2);
    expect(r.firstGreen).toBe(1); // 首拍红的文件 firstGreen 不计
    expect(r.ratio).toBeCloseTo(2 / 3, 10);
  });
});

describe("verify-census CLI 命令", () => {
  it("默认打印人读三行（sessions/withVerify/firstGreen）", () => {
    const ws = makeWorkspace(threeScenarios);
    const out = execFileSync("node", ["--import", "tsx", SCRIPT, "--workspace", ws], {
      cwd: REPO_ROOT,
      encoding: "utf8",
    });
    const lines = out.split("\n").filter((l) => l.length > 0);
    expect(lines).toEqual(["sessions: 3", "withVerify: 2", "firstGreen: 1"]);
  });

  it("--json 打印完整 JSON 且字段一致", () => {
    const ws = makeWorkspace(threeScenarios);
    const out = execFileSync("node", ["--import", "tsx", SCRIPT, "--workspace", ws, "--json"], {
      cwd: REPO_ROOT,
      encoding: "utf8",
    });
    const r = JSON.parse(out) as ReturnType<typeof collectCensus>;
    expect(r.sessions).toBe(3);
    expect(r.withVerify).toBe(2);
    expect(r.firstGreen).toBe(1);
    expect(r.userTurns).toBe(5);
    expect(r.ratio).toBeCloseTo(2 / 3, 10);
    expect(r.skippedLines).toBe(0);
  });
});

args.new_string:
